    for f in sorted(glob.glob(d + '/sessions/*.jsonl'))[:3]:
        t = open(f).read()
        base = os.path.basename(f)
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
