    def is_gap_col(c):
        return c in {5, 6, 12, 13, 19, 20}

    # Gap rows (binary mask) - 2 rows of gap after each block
    def is_gap_row(r):
        # Gap rows at indices: 6-7, 13-14, 20-21
        return r in {6, 7, 13, 14, 20, 21}

    center_rows = [2, 9, 16, 23]

    for block_r in range(4):
